package org.jsoup.parser;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class TokenQueue_ESTest_test10 extends TokenQueue_ESTest_scaffolding {

    @Test(timeout = 4000)
    public void test10() throws Throwable {
        String cssIdentifierWithLeadingHyphenDigitAndSpecialCharacters = "-8Lc8X#GxA*";
        String expectedEscapedCssIdentifier = "-\\38 Lc8X\\#GxA\\*";

        String escapedCssIdentifier = TokenQueue.escapeCssIdentifier(
                cssIdentifierWithLeadingHyphenDigitAndSpecialCharacters);

        assertEquals(expectedEscapedCssIdentifier, escapedCssIdentifier);
    }
}
